from pathlib import Path
import json
P=Path(__file__).resolve().parent;R=P.parent.parent
cfg=[]
for gear in ['bare','helmet']:
 for direction,gait,bridge in [('east','bill-carry-east-gait-v3','bill-carry-start-east-v4'),('south','bill-carry-south-gait-v2','bill-carry-start-south-v1'),('west','bill-carry-west-gait-v2','bill-carry-start-west-v2'),('north','bill-carry-north-gait-v1','bill-carry-start-north-v1')]:
  g=json.loads((R/f'character/{gait}/{gear}-manifest.json').read_text())['states'][0];b=json.loads((R/f'character/{bridge}/{gear}-manifest.json').read_text())['states'][0]
  cfg.append({'gear':gear,'direction':direction,'master':'/'+b['frameFiles'][0].removeprefix('res://'),'gait':['/'+f.removeprefix('res://') for f in g['frameFiles']],'bridge':['/'+f.removeprefix('res://') for f in b['frameFiles']],'gaitDurations':g['frameDurationsMs'],'bridgeDurations':b['frameDurationsMs'],'resume':104 if direction=='east' else 139})
html='''<!doctype html><meta charset="utf-8"><title>Bill — four-direction carrying comparison</title><style>body{font:16px system-ui;background:#182932;color:#dde8e9;margin:24px}canvas{background:#22343e;max-width:100%;border:1px solid #465e69}select,button{margin:8px}h2{font-size:19px}img{max-width:100%}</style><h1>Bill — carrying consistency</h1><p>Directional held master on the left, current moving candidate on the right.</p><label>Equipment <select id="gear"><option value="bare">Bare</option><option value="helmet">Helmet</option></select></label><label>Size <select id="size"><option>82</option><option>148</option></select></label><label>Motion <select id="mode"><option value="gait">Walk loop</option><option value="bridge">First step and walk</option></select></label><button id="play">Pause</button><p id="clock"></p>CANVASES<p>Source-only comparison at one fixed review pivot. The latest East and West corrections have separate room evidence. Natural routes, interruptions and saved handoffs remain open.</p><script>const cfg=CONFIG,images=new Map();for(const c of cfg)for(const p of [c.master,...c.gait,...c.bridge])if(!images.has(p)){const im=new Image();im.src=p;images.set(p,im)}let time=0,last=performance.now(),playing=true;document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Play'};for(const id of ['mode','gear'])document.querySelector('#'+id).onchange=()=>time=0;function choose(paths,durations,ms){let n=0;for(let i=0;i<paths.length;i++){n+=durations[i];if(ms<n)return paths[i]}return paths.at(-1)}function draw(now){if(playing)time+=now-last;last=now;const gear=document.querySelector('#gear').value,scale=Number(document.querySelector('#size').value)/148,mode=document.querySelector('#mode').value;for(const c of cfg.filter(c=>c.gear===gear)){let p=c.master,t=mode==='gait'?time%840:time%2500-250;if(mode==='gait')p=choose(c.gait,c.gaitDurations,t);else if(t>=0)p=t<320?choose(c.bridge,c.bridgeDurations,t):choose(c.gait,c.gaitDurations,(t-320+c.resume)%840);const canvas=document.querySelector('#'+c.direction),ctx=canvas.getContext('2d');ctx.clearRect(0,0,480,265);for(const [path,x] of [[c.master,120],[p,360]]){const im=images.get(path);if(im.complete&&im.naturalWidth)ctx.drawImage(im,x-128*scale,240-224*scale,256*scale,256*scale)}}document.querySelector('#clock').textContent=mode==='gait'?Math.round(time%840)+'ms / 840ms loop':'Held → first step → walking';requestAnimationFrame(draw)}requestAnimationFrame(draw)</script>'''
html=html.replace('CANVASES',''.join(f'<h2>{d.title()} · master / candidate</h2><canvas id="{d}" width="480" height="265"></canvas>' for d in ['east','south','west','north'])).replace('CONFIG',json.dumps(cfg));(P/'index.html').write_text(html,encoding='utf-8');print('Saved current eight-profile fixed-pivot animated comparison')
